from itertools import product

def bad_set(d, p):
    return [(a1, a2) for a1, a2 in product(range(p), range(p))
            if (d[0]*a1 + d[1]*a2) % p == 0]

for p in (5, 7, 11, 13):
    sizes = {len(bad_set((d1, d2), p))
             for d1, d2 in product(range(p), range(p)) if (d1, d2) != (0, 0)}
    print(p, sorted(sizes), sizes == {p})

