    forbidden := {}
    for d in D:
        if d.2 != 0: forbidden.add( (-d.1 * inverse(d.2, p)) mod p )
    for t in 0 .. p-1:
        if t not in forbidden: return (1, t)
    for t in 0 .. p-1:                 // fallback slice (t,1)
        if all <d,(t,1)> != 0: return (t, 1)
    return FAIL

